    62	/**
    63	 * Metadata from a managed receipt importer is the sole permitted HEAD advance
    64	 * between the signed review run and receipt admission. The check is deliberately
    65	 * mechanical: ancestry, exact command-owned subject, and exact story-local
    66	 * changed paths must all hold for every intervening commit.
    67	 */
    68	function hasOnlyManagedReviewImporterCommits(args: {
    69	  gitCwd: string;
    70	  metadataRoot: string;
    71	  storyId: string;
    72	  reviewedHeadHash: string;
    73	  liveHeadHash: string;
    74	}): boolean {
    75	  if (args.reviewedHeadHash === args.liveHeadHash) return true;
    76	  try {
    77	    execFileSync('git', ['merge-base', '--is-ancestor', args.reviewedHeadHash, args.liveHeadHash], {
    78	      cwd: args.gitCwd,
    79	      stdio: ['ignore', 'ignore', 'ignore'],
    80	    });
    81	    const commits = execFileSync('git', ['rev-list', '--reverse', `${args.reviewedHeadHash}..${args.liveHeadHash}`], {
    82	      cwd: args.gitCwd,
    83	      encoding: 'utf8',
    84	      stdio: ['ignore', 'pipe', 'pipe'],
    85	    }).trim().split('\n').filter(Boolean);
    86	    if (commits.length === 0) return false;
    87	    const expectedSubject = `lattice: record ${args.storyId} managed_review_evidence_import metadata`;
    88	    // Never accept merely story-id-looking paths.  The sole permitted HEAD
    89	    // advance is the configured canonical story directory, and only the exact
    90	    // importer artifacts under that directory.  A same-subject commit against
    91	    // another .lattice tree must remain non-admissible.
    92	    const configuredStoryDir = loadConfig(args.metadataRoot).storyDir;
    93	    const canonicalStoryDir = relative(
    94	      args.gitCwd,
    95	      resolve(args.metadataRoot, configuredStoryDir, args.storyId),
    96	    ).replace(/\\/g, '/').replace(/^\.\//, '');
    97	    if (!canonicalStoryDir || canonicalStoryDir === '..' || canonicalStoryDir.startsWith('../')) return false;
    98	    const canonicalImporterArtifacts = new Set([
    99	      `${canonicalStoryDir}/review-passes.json`,
   100	      `${canonicalStoryDir}/findings.json`,
   101	      `${canonicalStoryDir}/process-events.jsonl`,
   102	    ]);
   103	    return commits.every(commit => {
   104	      const subject = execFileSync('git', ['show', '-s', '--format=%s', commit], {
   105	        cwd: args.gitCwd,
   106	        encoding: 'utf8',
   107	        stdio: ['ignore', 'pipe', 'pipe'],
   108	      }).trim();
   109	      if (subject !== expectedSubject) return false;
   110	      const files = execFileSync('git', ['diff-tree', '--no-commit-id', '--name-only', '-r', commit], {
   111	        cwd: args.gitCwd,
   112	        encoding: 'utf8',
   113	        stdio: ['ignore', 'pipe', 'pipe'],
   114	      }).trim().split('\n').filter(Boolean);
   115	      const names = new Set(files.map(file => file.split('/').at(-1)));
   116	      return files.length > 0
   117	        && files.every(file => canonicalImporterArtifacts.has(file.replace(/\\/g, '/')))
   118	        && (names.has('review-passes.json') || names.has('findings.json'));
   119	    });
   120	  } catch {
   121	    return false;
   122	  }
   123	}
