   254	export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
   255	  if (run.assembledPrompt) return run.assembledPrompt;
   256	  // A no-envelope ReviewRun predates modular prompt assembly. Its signed
   257	  // promptHash therefore names the frozen legacy role body, regardless of a
   258	  // later rollout/template-mode change in the live project configuration.
