   272	/**
   273	 * Render the signed ReviewRun prompt for a managed provider without turning
   274	 * its canonical audit workspace into a provider execution instruction.
   275	 *
   276	 * `assembledPrompt` remains the signed, durable review context.  Formal
   277	 * managed-review providers instead receive this derived rendering and execute
   278	 * in the scratch cwd sealed by managed-host-run.  Native reviewer dispatch
   279	 * continues to receive the unmodified assembled prompt.
   280	 */
   281	export function renderManagedReviewerProviderPrompt(basePrompt: string, canonicalRoot: string): string {
   282	  const primaryWorktree = canonicalRoot.trim();
   283	  if (!primaryWorktree) return basePrompt;
   284	  return basePrompt
   285	    .split(/\r?\n/)
   286	    .filter(line => {
   287	      const trimmed = line.trim();
   288	      return !(trimmed.includes(primaryWorktree)
   289	        && /^working directory(?:\s*\(subagent must cd here\))?\s*:/i.test(trimmed));
   290	    })
   291	    .join('\n');
   292	}
