   294	function renderManagedReviewerCanonicalReportSnapshot(
   295	  statuses: readonly ManagedReviewCanonicalReportStatus[],
   296	): string[] {
   297	  const byCommand = new Map(statuses.map(status => [status.command, status]));
   298	  if (byCommand.size !== MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.length
   299	    || statuses.length !== MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.length
   300	    || MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.some(command => !byCommand.has(command))) {
   301	    throw new Error('managed reviewer: canonical report snapshot must contain each required command exactly once');
   302	  }
   303	  const validStatus = new Set(['pass', 'fail', 'inconclusive', 'missing', 'unavailable']);
   304	  const validCode = /^[A-Za-z0-9_.:-]{1,96}$/;
   305	  const rows = MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.map(command => {
   306	    const entry = byCommand.get(command)!;
   307	    if ((entry.availability !== 'available' && entry.availability !== 'unavailable')
   308	      || !validStatus.has(entry.status)
   309	      || (entry.blocking !== null && typeof entry.blocking !== 'boolean')
   310	      || !Array.isArray(entry.codes)) {
   311	      throw new Error(`managed reviewer: invalid canonical report snapshot entry for ${command}`);
   312	    }
   313	    const codes = entry.codes
   314	      .filter(code => typeof code === 'string' && validCode.test(code))
   315	      .slice(0, 12);
   316	    return `${command}: availability=${entry.availability}; status=${entry.status}; blocking=${entry.blocking ?? 'unknown'}; codes=${codes.join(',') || 'none'}`;
   317	  });
   318	  return [
   319	    '--- BEGIN CONTROLLER-FETCHED CANONICAL REPORT STATUS ---',
   320	    'These bounded read-only status projections were evaluated by the controller against the signed canonical review context before this provider launched.',
   321	    'This managed-only execution-boundary instruction overrides any earlier generic reviewer request to read these reports directly. Consume these entries directly. Do NOT invoke acceptance_topology_check, pre_review_check_read, acceptance_rollout_report_read, or acceptance_rollout_check from this scratch worktree.',
   322	    'An unavailable entry is an honest controller-evaluation limitation; report it if relevant and do not retry that CLI reader from the provider.',
   323	    ...rows,
   324	    '--- END CONTROLLER-FETCHED CANONICAL REPORT STATUS ---',
   325	  ];
   326	}
